// The versioned evidence of ENG-54 (outputs/evidencias/retry-rate-limit.txt):
// it must exist, show the five scenarios and hold nothing that varies or that
// looks like a secret. The file is generated by `npm run demo:falhas`, never
// edited by hand.
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { DEMO_API_KEY } from "../scripts/demo-falhas/config.js";

const FILE = fileURLToPath(
  new URL("../outputs/evidencias/retry-rate-limit.txt", import.meta.url),
);
const text = readFileSync(FILE, "utf8");

describe("outputs/evidencias/retry-rate-limit.txt", () => {
  it("has the five scenarios and a clean result", () => {
    const headers = text.match(/^== Cenário [1-5]: .+ ==$/gm) ?? [];

    expect(headers).toHaveLength(5);
    expect(text).toContain("5 de 5 cenários conferem");
    expect(text).toContain("Código de saída 0.");
    expect(text).not.toContain("FALHOU");
    expect(text).not.toContain("DIVERGE");
  });

  it("shows the warnings of new tries and the wait of each one", () => {
    expect(text.match(/^ {2}Aviso: /gm)).toHaveLength(8);
    expect(text.match(/^ {2}Espera planejada: /gm)).toHaveLength(8);
    expect(text).toContain("(origem: Retry-After do provedor)");
    expect(text).toContain("Desisti depois de 4 tentativas");
  });

  it("holds no key, port, header of credential or date", () => {
    expect(text).not.toMatch(/sk-/i);
    expect(text).not.toContain(DEMO_API_KEY);
    expect(text).not.toMatch(/authorization|bearer/i);
    expect(text).not.toMatch(/:\d{4,5}\b/);
    expect(text).not.toMatch(/\b\d{4}-\d{2}-\d{2}\b/);
    expect(text).not.toMatch(/[A-Za-z]:\\/);
  });

  it("is plain text with Unix line breaks, ending with one", () => {
    expect(text.endsWith("\n")).toBe(true);
    expect(text).not.toContain("\r");
  });
});
